SELECT 
  FROM flt15_tr_status
 WHERE flt15_company_id = #{companyId}
   AND flt15_person_id  = #{personId}
   AND flt15_date       = CAST(#{stdDate} AS date)

mapper.update:
UPDATE flt15_tr_status
   SET flt15_note = #{note}
 WHERE flt15_tr_status_id = #{trStatusId}
   AND flt15_company_id   = #{companyId}

